const screen=document.getElementById('screen');
const data={registered:false,visited:false,published:true,cancelled:false,title:'Встреча IT сообщества',rooms:[{name:'Главный зал',capacity:100}],sessions:[{name:'Открытие и знакомство',start:'10:00',end:'10:30',room:'Главный зал'}]};
const link=(route,text,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="#${route}">${text}</a>`;
const notice=(text,type='')=>`<div role="status" class="notice ${type}">${text}</div>`;
const testing=(items)=>`<div class="testbar"><label for="state">Показать состояние для проверки макета</label><select id="state"><option value="normal">Обычное состояние</option>${items.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><div id="state-result" aria-live="polite"></div></div>`;
const heading=(role,title)=>`<span class="badge">${role}</span><h1>${title}</h1>`;
const escaped=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const route=location.hash.slice(1)||'event';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));
 const views={
 event:()=>`<div class="hero"><span>Бесплатное мероприятие</span><h1>${escaped(data.title)}</h1><p class="muted">7 ноября · 10:00–18:00 · Москва</p><p>Встреча разработчиков: доклады, обмен опытом и новые знакомства.</p><div class="actions">${data.cancelled?notice('Мероприятие отменено'):!data.published?notice('Мероприятие пока не опубликовано'):link(data.registered?'ticket':'register',data.registered?'Открыть билет':'Зарегистрироваться')}</div></div><div class="grid"><section class="card"><h2>Площадка</h2><p>Учебный центр · Главный зал</p><p class="muted">Вместимость 100 участников</p></section><section class="card"><h2>Программа</h2>${data.sessions.map(s=>`<div class="entry"><strong>${escaped(s.start)}–${escaped(s.end)}</strong><p>${escaped(s.name)}</p><span class="muted">${escaped(s.room)}</span></div>`).join('')}</section></div>${testing([['full','Места закончились'],['closed','Регистрация закрыта'],['loading','Загрузка'],['network','Ошибка сети']])}`,
 register:()=>`${heading('Участник','Регистрация на мероприятие')}<p class="muted">${escaped(data.title)} · участие бесплатное</p><form id="registration" class="card"><label for="name">Имя и фамилия</label><input id="name" autocomplete="name" required placeholder="Имя Фамилия"><label for="email">Электронная почта</label><input id="email" type="email" autocomplete="email" required placeholder="mail@example.ru"><p><label><input id="consent" type="checkbox" required> Согласен на обработку данных для регистрации</label></p><div id="form-result" aria-live="polite"></div><div class="actions"><button>Получить билет</button>${link('event','Назад',true)}</div></form>${testing([['guest','Требуется вход'],['duplicate','Уже зарегистрирован'],['full','Мест нет'],['network','Ошибка сети']])}`,
 tickets:()=>`${heading('Участник','Мои регистрации')}<section class="card">${data.registered?`<span class="badge">${data.visited?'Посещение подтверждено':'Регистрация активна'}</span><h2>${escaped(data.title)}</h2><p>7 ноября · Москва</p><div class="actions">${link('ticket','Открыть билет')}${!data.visited?'<button class="secondary" id="cancel-registration">Отменить регистрацию</button>':''}</div>`:`<h2>Пока нет регистраций</h2><p class="muted">Выберите мероприятие и получите электронный билет.</p>${link('event','Посмотреть мероприятие')}`}</section>${testing([['network','Не удалось загрузить'],['cancelled','Отменённое мероприятие']])}`,
 ticket:()=>`${heading('Участник','Электронный билет')}<div class="card ticket"><span class="badge">${data.cancelled?'Мероприятие отменено':data.registered?(data.visited?'Использован':'Активен'):'Пример билета'}</span><h2>${escaped(data.title)}</h2><p>7 ноября · 10:00 · Главный зал</p><div class="qr">Место QR кода<br>Не является билетом</div><p class="muted">Покажите билет сотруднику на входе. Настоящий QR код появится после подключения сервера.</p>${link('tickets','Мои регистрации',true)}</div>${testing([['revoked','Билет аннулирован'],['access','Чужой билет'],['network','Ошибка сети']])}`,
 dashboard:()=>`${heading('Организатор','Мои мероприятия')}<p class="muted">Создавайте мероприятия и следите за регистрациями.</p><div class="actions">${link('editor','Создать мероприятие')}</div><section class="card"><span class="badge">${data.cancelled?'Отменено':data.published?'Опубликовано':'Черновик'}</span><h2>${escaped(data.title)}</h2><p>7 ноября · Москва · 100 мест</p><div class="actions">${link('editor','Редактировать')}${link('stats','Статистика',true)}${link('program','Программа',true)}</div></section>${testing([['empty','Нет мероприятий'],['access','Нет доступа'],['network','Ошибка загрузки']])}`,
 editor:()=>`${heading('Организатор','Редактор мероприятия')}<form id="event-form" class="card"><label for="title">Название</label><input id="title" required value="${escaped(data.title)}"><div class="grid"><div><label for="start">Начало</label><input id="start" type="datetime-local" required value="2026-11-07T10:00"></div><div><label for="end">Окончание</label><input id="end" type="datetime-local" required value="2026-11-07T18:00"></div></div><label for="capacity">Лимит участников</label><input id="capacity" type="number" min="1" max="100" required value="100"><label for="description">Описание</label><textarea id="description">Встреча разработчиков: доклады, обмен опытом и новые знакомства.</textarea><div id="form-result" aria-live="polite"></div><div class="actions"><button>Сохранить черновик</button><button type="button" id="publish">Опубликовать</button><button type="button" class="secondary" id="cancel-event">Отменить мероприятие</button>${link('program','Программа и площадки',true)}</div></form>${testing([['access','Нет права редактирования'],['network','Ошибка сохранения']])}`,
 program:()=>`${heading('Организатор','Программа и площадки')}<div class="grid"><section class="card"><h2>Площадки</h2>${data.rooms.map(r=>`<div class="entry">${escaped(r.name)} · ${r.capacity} мест</div>`).join('')}<form id="room-form"><label for="room-name">Название зала</label><input id="room-name" required><label for="room-capacity">Вместимость</label><input id="room-capacity" type="number" min="1" required value="50"><div class="actions"><button>Добавить зал</button></div></form></section><section class="card"><h2>Программа</h2>${data.sessions.map(s=>`<div class="entry">${escaped(s.start)}–${escaped(s.end)}<p>${escaped(s.name)}</p><small>${escaped(s.room)}</small></div>`).join('')}<form id="session-form"><label for="session-name">Название выступления</label><input id="session-name" required><div class="grid"><div><label for="session-start">Начало</label><input id="session-start" type="time" required value="10:30"></div><div><label for="session-end">Конец</label><input id="session-end" type="time" required value="11:00"></div></div><label for="session-room">Зал</label><select id="session-room">${data.rooms.map(r=>`<option>${escaped(r.name)}</option>`).join('')}</select><div id="form-result" aria-live="polite"></div><div class="actions"><button>Добавить выступление</button></div></form></section></div>`,
 stats:()=>`${heading('Организатор','Статистика мероприятия')}<p class="muted">${escaped(data.title)} · пример показателей</p><div class="grid"><section class="card">Активных регистраций<span class="number">3</span></section><section class="card">Уникальных посетителей<span class="number">2</span></section><section class="card">Доля посещения<span class="number">66,7%</span></section></div><section class="card"><h2>Посещение</h2><p>2 участника посетили мероприятие, 1 ещё не пришёл.</p><progress max="3" value="2" aria-label="Посетили 2 из 3"></progress><p class="muted">Повторное сканирование не увеличивает число посетителей.</p><button id="csv">Скачать пример CSV</button></section>${testing([['empty','Нет регистраций'],['access','Нет доступа'],['network','Ошибка загрузки']])}`,
 scanner:()=>`${heading('Сотрудник','Проверка билетов')}<p class="muted">${escaped(data.title)} · вход в Главный зал</p><section class="card"><div class="camera">Область камеры<br>В прототипе используйте ввод ниже</div><form id="scan-form"><label for="token">Код билета</label><input id="token" required placeholder="Для примера введите PASSGO-DEMO"><div class="actions"><button>Проверить билет</button></div></form><div id="scan-result" aria-live="polite"></div></section>${testing([['duplicate','Повторное сканирование'],['invalid','Недействительный билет'],['wrong','Другое мероприятие'],['camera','Камера недоступна'],['network','Нет интернета'],['time','Вне времени прохода']])}`
 };screen.innerHTML=views[route]?views[route]():`${heading('PassGo','Страница не найдена')}${link('event','К мероприятию')}`;bind();}
const messages={full:'Свободные места закончились. Регистрация недоступна.',closed:'Регистрация закрыта.',loading:'Загружаем данные…',network:'Нет связи с сервером. Повторите попытку. Изменения и посещение не подтверждены.',guest:'Войдите в аккаунт, чтобы зарегистрироваться.',duplicate:'Вы уже зарегистрированы или билет уже использован. Повторное действие не выполняется.',cancelled:'Мероприятие отменено. Билет не действует.',revoked:'Регистрация отменена. Билет аннулирован.',access:'У вас нет доступа к этим данным.',empty:'Пока нет данных. Начните с создания мероприятия или регистрации.',invalid:'Билет не найден или аннулирован. Проход не подтверждён.',wrong:'Билет относится к другому мероприятию. Проход не подтверждён.',camera:'Камера недоступна. Введите код билета вручную.',time:'Проход доступен за 60 минут до начала и до окончания мероприятия.'};
function bind(){const on=(id,event,fn)=>document.getElementById(id)?.addEventListener(event,fn);on('state','change',e=>{document.getElementById('state-result').innerHTML=e.target.value==='normal'?'':notice(messages[e.target.value],['camera','loading','empty'].includes(e.target.value)?'':'error');});
 on('registration','submit',e=>{e.preventDefault();if(data.cancelled||!data.published){document.getElementById('form-result').innerHTML=notice('Регистрация недоступна.','error');return;}data.registered=true;data.visited=false;location.hash='ticket';});
 on('cancel-registration','click',()=>{if(confirm('Отменить регистрацию? Текущий билет перестанет действовать.')){data.registered=false;render();}});
 const save=publish=>{const f=document.getElementById('event-form');if(!f.reportValidity())return;if(document.getElementById('end').value<=document.getElementById('start').value){document.getElementById('form-result').innerHTML=notice('Окончание должно быть позже начала.','error');return;}data.title=document.getElementById('title').value;data.published=publish;data.cancelled=false;document.getElementById('form-result').innerHTML=notice(publish?'Мероприятие опубликовано в прототипе.':'Черновик сохранён в памяти вкладки.','success');};
 on('event-form','submit',e=>{e.preventDefault();save(false);});on('publish','click',()=>save(true));on('cancel-event','click',()=>{if(confirm('Отменить мероприятие? Его билеты перестанут действовать.')){data.cancelled=true;location.hash='dashboard';}});
 on('room-form','submit',e=>{e.preventDefault();const name=document.getElementById('room-name').value.trim();if(!name||data.rooms.some(r=>r.name===name)){alert('Введите уникальное название зала.');return;}data.rooms.push({name,capacity:Number(document.getElementById('room-capacity').value)});render();});
 on('session-form','submit',e=>{e.preventDefault();const start=document.getElementById('session-start').value,end=document.getElementById('session-end').value,room=document.getElementById('session-room').value;const error=end<=start?'Окончание должно быть позже начала.':start<'10:00'||end>'18:00'?'Выступление должно попадать в время мероприятия.':data.sessions.some(s=>s.room===room&&start<s.end&&end>s.start)?'В этом зале уже есть выступление в указанное время.':null;if(error){document.getElementById('form-result').innerHTML=notice(error,'error');return;}data.sessions.push({name:document.getElementById('session-name').value,start,end,room});render();});
 on('scan-form','submit',e=>{e.preventDefault();let text,type='error';if(data.cancelled||!data.registered)text='Активная регистрация не найдена. Сначала пройдите регистрацию в прототипе.';else if(document.getElementById('token').value!=='PASSGO-DEMO')text=messages.invalid;else if(data.visited)text=messages.duplicate;else{data.visited=true;text='Посещение подтверждено в демонстрационном сценарии.';type='success';}document.getElementById('scan-result').innerHTML=notice(text,type);});
 on('csv','click',()=>{const blob=new Blob(['\ufeffПоказатель;Значение\r\nАктивные регистрации;3\r\nУникальные посетители;2\r\nДоля посещения;66,7%\r\n'],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='passgo-demo-statistics.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
window.addEventListener('hashchange',render);render();
